<?php $pageResources=ohsc_resources_for_page($db,$key); ?>
<section style="margin-top:30px;border-top:1px solid #ccc;padding-top:20px"><h3>Resources on this page</h3>
<p class="tools-actions"><a href="<?php echo ohsc_h($base_url.'/admin/career-resource?page='.rawurlencode($key)); ?>">Add resource to this page</a> <a href="<?php echo ohsc_h($base_url.'/admin/career-resources?page='.rawurlencode($key)); ?>">Manage resources</a></p>
<table class="tools" width="100%"><tr><th>Resource</th><th>Status</th><th>Actions</th></tr>
<?php if (!$pageResources) { ?><tr><td colspan="3">No resources on this page yet.</td></tr><?php } ?>
<?php foreach ($pageResources as $r) { ?><tr><td><?php echo ohsc_h($r['title']); ?></td><td><?php echo $r['is_active']?'Published':'Draft'; ?></td><td><a href="<?php echo ohsc_h($base_url.'/admin/career-resource?id='.$r['resource_id'].'&page='.rawurlencode($key)); ?>">Update / files</a> <form method="post" action="<?php echo ohsc_h($base_url); ?>/admin/career-resources" style="display:inline" onsubmit="return confirm('Delete this resource? It can be restored from Deleted resources.');"><input type="hidden" name="csrf" value="<?php echo ohsc_h($_SESSION['ohsc_tools_csrf']); ?>"><input type="hidden" name="resource_id" value="<?php echo (int)$r['resource_id']; ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="return_page" value="<?php echo ohsc_h($key); ?>"><button>Delete</button></form></td></tr><?php } ?></table></section>
